#!/usr/bin/env python3
"""Phase J — minimal-change reconstruction of the revised manuscript on the submitted text (v1).
Writes the section files read by assemble_lar.py (manuscript/revised_v2/*.md) from three sources:
  * v1 sentences (revision_v2/submission/LAR_v1_text.md) kept verbatim or minimally edited (number substitution from numbers.tsv),
  * v2 (H-8) donor paragraphs for the NEW components (revision_v2/audit/pre_numbering/*.md, which still carry [CITE key] markers),
  * a few fresh sentences required by the instruction.
Every number is a «key|fmt» placeholder resolved from manuscript/revised_v2/generated/numbers.tsv. Citations are [CITE key]
markers (v1 numeric citations mapped to keys), numbered afterwards by number_citations.py.
Each paragraph carries a trigger tag (KEEP, CORR, R1-M1 … R2-C4, NEW-ID, NEW-NC, NEW-DEC, NEW-WS, NEW-WE, NEW-F1, NEW-ASM, NEW-PD,
REF) written to revision_v2/ledger_paragraph_triggers.tsv for make_change_ledger.py. Usage: build_phase_j.py"""
import re, csv, os
P="/usr/local/jupyter/FVB_bias"; M=f"{P}/manuscript/revised_v2"; D=f"{P}/revision_v2/audit/pre_numbering"
N={r["key"]:r["value"] for r in csv.DictReader(open(f"{M}/generated/numbers.tsv"), delimiter="\t")}
SUP=str.maketrans("0123456789-","⁰¹²³⁴⁵⁶⁷⁸⁹⁻")
def sci(x):
    x=float(x)
    if x<1e-15: return "< 10⁻¹⁵"
    m,e=f"{x:.1e}".split("e"); return f"= {m} × 10{str(int(e)).translate(SUP)}"
def fmt(key, f):
    v=N[key]
    if f=="s": return v
    x=float(v)
    if f=="p": return "p "+sci(x)
    if f=="sci": return sci(x).lstrip("= ")
    if f=="M": return f"{x/1e6:.1f} million"
    if f=="pct2": return f"{x:.2f}%"
    if f=="pct1": return f"{x:.1f}%"
    if f=="abs2": return f"{abs(x):.2f}"
    if f=="abs3": return f"{abs(x):.3f}"
    if f=="d": return f"{int(round(x))}"
    if f==",d": return f"{int(round(x)):,}"
    if f=="w":  # number word for small integers (sentence starts)
        W={2:"Two",3:"Three",4:"Four",5:"Five",11:"Eleven",6:"Six",7:"Seven",8:"Eight",9:"Nine",10:"Ten",12:"Twelve",15:"Fifteen",16:"Sixteen",18:"Eighteen",19:"Nineteen",35:"Thirty-five",37:"Thirty-seven",46:"Forty-six",56:"Fifty-six",57:"Fifty-seven",82:"Eighty-two"}
        return W[int(round(x))]
    if f=="wl": return fmt(key,"w").lower()
    return format(x, f)
def R(s):  # resolve «key|fmt» placeholders
    return re.sub(r"«([^|»]+)\|([^»]+)»", lambda m: fmt(m.group(1), m.group(2)), s)
def v2sec(fname, heading):
    """paragraphs (list of str) of the '## heading' section of a pre_numbering donor file"""
    txt=open(f"{D}/{fname}", encoding="utf-8").read(); parts=re.split(r"^## ", txt, flags=re.M)
    for p in parts:
        if p.startswith(heading):
            body=p[len(heading):].strip("\n"); return [x.strip() for x in re.split(r"\n\s*\n", body) if x.strip() and not x.strip().startswith("<!--")]
    raise KeyError(heading)
def v2par(fname, start):
    txt=open(f"{D}/{fname}", encoding="utf-8").read()
    for x in re.split(r"\n\s*\n", txt):
        if x.strip().startswith(start): return x.strip()
    raise KeyError(start)
