C=open(f"{D}/supplementary_table_captions.md", encoding="utf-8").read()
def v2cap(start):
    parts=[x.strip() for x in re.split(r"\n\s*\n", C)]
    for i,x in enumerate(parts):
        if x.startswith("**Supplementary Table "+start): return parts[i+1:i+2] if start in ("S2.","S5.") else [p for p in parts[i+1:] if not p.startswith("**Supplementary Table") and p!="---"][:({"S1.":2,"S3.":6,"S4.":1}[start])]
    raise KeyError(start)
